// Diagnostic controller/transport isolation only. This is not two-player gameplay.
export const version=1;
export function createAdapter(ctx){let root,canvas,ac,node,osc,raf=0,closed=false,running=false,frames=0;const held=new Map();
 const publish=()=>{globalThis.__diagnostic={label:'Diagnostic only — not real two-player gameplay',frames,held:[...held.values()].map(e=>({...e}))};};
 const tick=()=>{if(closed)return;raf=requestAnimationFrame(tick);if(!running)return;frames++;const g=canvas.getContext('2d');g.fillStyle=frames%120<60?'#246':'#462';g.fillRect(0,0,256,240);g.fillStyle='#fff';g.fillText('Transport diagnostic '+frames,10,25);for(const e of held.values())g.fillText('seat '+e.seat+' '+e.control,10,e.seat*65);publish();};
 function dispose(){if(closed)return;closed=true;running=false;cancelAnimationFrame(raf);held.clear();osc?.stop();node?.disconnect();root?.remove();publish();return ac?.close();}ctx.scope.defer(dispose);
 return {version:1,packageId:ctx.package.id,artifactDigest:ctx.package.artifactDigest,load(){root=document.createElement('div');root.textContent='Diagnostic only — not real two-player gameplay';canvas=document.createElement('canvas');canvas.width=256;canvas.height=240;root.append(canvas);ctx.view.append(root);tick();},start(){running=true;if(!ac){ac=new AudioContext();node=ac.createGain();node.gain.value=.08;node.connect(ac.destination);osc=ac.createOscillator();osc.frequency.value=440;osc.connect(node);osc.start();}void ac.resume();ctx.changed();},resume(){this.start();},pause(){running=false;held.clear();publish();},reset(){held.clear();frames=0;publish();},dispose,input(e){if(!running&&e.pressed)return false;if(e.pressed)held.set(e.source,e);else held.delete(e.source);publish();return true;},releaseAll(){held.clear();publish();},snapshot:()=>({ready:!closed,running,loading:false,closed,message:'Diagnostic only — not real two-player gameplay'}),surfaces:()=>({view:root,video:canvas,audio:{kind:'web-audio',getNodes:()=>({context:ac,node})}})};
}
